(() => {
  const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
  const $=s=>document.querySelector(s);
  const ui={lives:$('#lives'),cash:$('#cash'),wave:$('#wave'),wavecap:$('#wavecap'),status:$('#status'),toast:$('#toast'),overlay:$('#overlay'),progress:$('#progress'),start:$('#startwave'),next:$('#nextwave'),desc:$('#wavedesc'),list:$('#towerlist'),box:$('#selectedbox'),sname:$('#selectedname'),slevel:$('#selectedlevel'),upgrade:$('#upgrade'),sell:$('#sell'),auto:$('#autowave'),autonote:$('#autonote')};
  // 10 pratos internacionais novos: cada técnica tem um alvo favorito.
  const kinds=[
    {id:'pipoca',name:'Pipoqueira',country:'Brasil',emoji:'🍿',cost:60,range:112,rate:.75,damage:16,color:'#f5c95d',desc:'Rajada rápida · equilibrada'},
    {id:'pizza',name:'Pizza giratória',country:'Itália',emoji:'🍕',cost:95,range:142,rate:1.28,damage:37,color:'#ff8959',effect:'splash',weak:['splitter','horde'],desc:'Explosão · boa contra hordas'},
    {id:'soda',name:'Canhão de refri',country:'EUA',emoji:'🥤',cost:125,range:97,rate:.42,damage:10,color:'#8de0c2',effect:'slow',weak:['burrower'],desc:'Bolhas desacelerantes · pega escavadores'},
    {id:'sushi',name:'Sushi de precisão',country:'Japão',emoji:'🍣',cost:105,range:145,rate:1.05,damage:25,color:'#82d4c2',effect:'poison',weak:['medic','specter'],desc:'Veneno · revela fantasmas e curandeiros'},
