function spawnEnemy(){if(spawnLeft<=0||enemies.length>=MAX_ACTIVE_ENEMIES)return;const boss=wavePattern%5===0&&spawnLeft===1,tier=wave>100?wavePattern:wave,unlocked=foes.filter(f=>tier>=f.min);let type,data;
  if(boss){type='boss';data={hp:470+tier*24,speed:17,reward:45,emoji:'🧟‍♂️',r:23}}
  else if(unlocked.length&&Math.random()<.48){const f=unlocked[Math.floor(Math.random()*unlocked.length)];type=f.id;data={hp:f.hp,speed:f.speed,reward:f.reward,emoji:f.emoji,r:f.r}}
  else{const roll=Math.random();type=tier>=15&&roll<.12?'tank':tier>2&&roll<.38?'runner':tier>1&&roll<.63?'brute':'walker';data={walker:{hp:48,speed:31,reward:9,emoji:'🧟',r:14},runner:{hp:32,speed:55,reward:12,emoji:'🧟‍♀️',r:14},brute:{hp:115,speed:22,reward:17,emoji:'🧟‍♂️',r:19},tank:{hp:210,speed:15,reward:24,emoji:'🧟‍♂️',r:20}}[type]}
  const scale=(wave>100?1+(wave-100)*.12:1)*difficulties[difficulty].hp*(1+(tier-1)*.025),hp=Math.round(data.hp*scale),f=foes.find(a=>a.id===type);
  enemies.push({x:path[0][0],y:path[0][1],seg:0,progress:0,hp,max:hp,speed:data.speed,reward:data.reward+Math.floor(tier/10),emoji:data.emoji,type,r:data.r,shield:f?.shield||0,maxShield:f?.shield||0,poison:0,burn:0,stun:0,phase:Math.random()*3,healTimer:1.2});spawnLeft--;
}
function makeParticles(x,y,color,n=6){for(let i=0;i<n;i++)particles.push({x,y,vx:(Math.random()-.5)*95,vy:(Math.random()-.7)*95,life:.45+Math.random()*.35,color,r:2+Math.random()*3})}
function finishEnemy(e){if(e.dead)return;e.dead=true;cash+=e.reward;makeParticles(e.x,e.y,'#d7f36a',9);log(`${foes.find(f=>f.id===e.type)?.name||'Zumbi'} derrotado! +${e.reward} petiscos`);if(foes.find(f=>f.id===e.type)?.split){for(let i=0;i<2;i++)enemies.push({...e,x:e.x+(i?8:-8),y:e.y+(i?6:-6),hp:Math.max(22,Math.round(e.max*.23)),max:Math.max(22,Math.round(e.max*.23)),speed:e.speed*1.35,reward:0,r:11,type:'mini',emoji:'🧟',dead:false,escaped:false,shield:0,poison:0,burn:0,stun:0})}}
